import * as React from "react";
import { Input as BaseInput } from "@base-ui-components/react/input";
import { cn } from "@/lib/utils";

// shadcn-style Input on the Base UI primitive. Every color is a theme token
// (audit: tokens-only); no @radix import (audit: no-raw-radix).
export function Input({ className, ...props }: React.ComponentProps<typeof BaseInput>) {
  return (
    <BaseInput
      className={cn(
        "h-9 w-full rounded-md border border-border bg-background px-3 py-1 text-sm text-foreground",
        "placeholder:text-muted-foreground",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand",
        "disabled:cursor-not-allowed disabled:opacity-50",
        "data-[invalid]:border-danger data-[invalid]:focus-visible:ring-danger",
        className
      )}
      {...props}
    />
  );
}
